    perform set_config('role', 'authenticated', true); perform set_config('request.jwt.claims', json_build_object('sub', '17200000-0000-4000-8000-000000000013', 'role', 'authenticated', 'aal', 'aal1')::text, true); begin perform public.captured_documents_summary(v_a); perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-72 · Resumen · ATAQUE: Facturación no ve el resumen','ok',false,'d','Se permitió'));
    exception when others then perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-72 · Resumen · ATAQUE: Facturación no ve el resumen','ok',sqlerrm like 'Solo el Administrador o el Super Admin%','d',left(sqlerrm,200))); end;
    perform set_config('role', 'authenticated', true); perform set_config('request.jwt.claims', json_build_object('sub', '17200000-0000-4000-8000-000000000021', 'role', 'authenticated', 'aal', 'aal1')::text, true); begin perform public.captured_documents_summary(v_a); perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-73 · Resumen · ATAQUE: Médico (cliente) no ve el resumen','ok',false,'d','Se permitió'));
    exception when others then perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-73 · Resumen · ATAQUE: Médico (cliente) no ve el resumen','ok',sqlerrm like 'Solo el Administrador o el Super Admin%','d',left(sqlerrm,200))); end;
    perform set_config('role', 'authenticated', true); perform set_config('request.jwt.claims', json_build_object('sub', '17200000-0000-4000-8000-000000000023', 'role', 'authenticated', 'aal', 'aal1')::text, true); begin perform public.captured_documents_summary(v_a); perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-74 · Resumen · ATAQUE: Administrador no ve el de otro cliente sin acceso (Médico de otro cliente)','ok',false,'d','Se permitió'));
    exception when others then perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-74 · Resumen · ATAQUE: Administrador no ve el de otro cliente sin acceso (Médico de otro cliente)','ok',sqlerrm like 'Solo el Administrador o el Super Admin%','d',left(sqlerrm,200))); end;
    perform set_config('role', 'anon', true); perform set_config('request.jwt.claims', '', true); begin perform public.captured_documents_summary(v_a); perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-75 · Resumen · ATAQUE: sin sesión (anon)','ok',false,'d','Se permitió'));
    exception when others then perform set_config('role', 'none', true); perform set_config('request.jwt.claims', '', true); v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-75 · Resumen · ATAQUE: sin sesión (anon)','ok',sqlerrm like '%permission denied%','d',left(sqlerrm,200))); end;
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-76 · Bitácora · El registro del documento queda en audit_log con quién lo hizo','ok',coalesce((exists (select 1 from public.audit_log l where l.table_name = 'documents' and l.operation = 'INSERT' and l.record_id = v_d1::text and l.user_id = '17200000-0000-4000-8000-000000000012'::uuid)), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-77 · Bitácora · La confirmación (UPDATE) también queda en audit_log','ok',coalesce((exists (select 1 from public.audit_log l where l.table_name = 'documents' and l.operation = 'UPDATE' and l.record_id = v_d1::text)), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-78 · Estructura · Las 5 columnas nuevas existen y los documentos viejos quedan como archivo sin OCR','ok',coalesce(((select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'documents' and column_name in ('capture_origin','sha256','ocr_data','ocr_confirmed','capture_pages')) = 5 and not exists (select 1 from public.documents where sha256 is null and ocr_data is null and capture_origin <> 'archivo' and storage_path like '%/normal.pdf')), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-79 · Estructura · Índice único parcial (organización, reclamación, huella)','ok',coalesce((exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'documents_org_entity_sha256_uidx' and indexdef like '%UNIQUE%' and indexdef like '%sha256 IS NOT NULL%')), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-80 · Estructura · Restricciones de origen, huella y páginas presentes','ok',coalesce(((select count(*) from pg_constraint where conrelid = 'public.documents'::regclass and conname in ('documents_capture_origin_check','documents_sha256_check','documents_capture_pages_check')) = 3), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-81 · Permisos · Las 3 funciones: authenticated sí, anon no','ok',coalesce((has_function_privilege('authenticated','public.register_captured_document(uuid,uuid,uuid,text,text,text,text,bigint,text,text,jsonb)','execute') and has_function_privilege('authenticated','public.confirm_document_ocr(uuid,jsonb)','execute') and has_function_privilege('authenticated','public.captured_documents_summary(uuid)','execute') and not has_function_privilege('anon','public.register_captured_document(uuid,uuid,uuid,text,text,text,text,bigint,text,text,jsonb)','execute') and not has_function_privilege('anon','public.confirm_document_ocr(uuid,jsonb)','execute') and not has_function_privilege('anon','public.captured_documents_summary(uuid)','execute')), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-82 · Seguridad · Las funciones son security definer con search_path vacío','ok',coalesce(((select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('register_captured_document','confirm_document_ocr','captured_documents_summary') and p.prosecdef and p.proconfig @> array['search_path=""']) = 3), false),'d',(null)::text));
    v_res := v_res || jsonb_build_array(jsonb_build_object('p','CA-83 · La migración 172 queda registrada','ok',coalesce((exists (select 1 from app.schema_migrations where version = '172')), false),'d',(null)::text));
    raise exception using errcode = 'P0001', message = 'sofa_qa_rollback';
  exception when others then
    if sqlerrm <> 'sofa_qa_rollback' then
      v_res := v_res || jsonb_build_array(jsonb_build_object('p','Error inesperado (las pruebas se detuvieron aquí)','ok',false,'d',left(sqlerrm, 300)));
    end if;
  end;
  perform set_config('role', 'none', true);
  perform set_config('request.jwt.claims', '', true);
  return query
    select 0, case when bool_and(coalesce((e->>'ok')::boolean, false)) then 'TODO OK' else 'REVISAR' end,   -- 5.10.0: una prueba sin resultado (NULL) cuenta como fallo; antes bool_and la ignoraba
           format('%s de %s pruebas aprobadas', count(*) filter (where coalesce((e->>'ok')::boolean, false)), count(*)), null::text
      from jsonb_array_elements(v_res) e
    union all
    select x.i::int, case when (x.e->>'ok')::boolean then 'APROBADA' else 'FALLÓ' end, x.e->>'p', x.e->>'d'
      from jsonb_array_elements(v_res) with ordinality as x(e, i)
    order by 1;
end
